col_left, col_right = st.columns([1.1, 1], gap="large")

with col_left:
    st.markdown('<p class="step-label">1 · Carregar Excel (mapa do dia)</p>', unsafe_allow_html=True)
    excel_file = st.file_uploader("Ficheiro Excel", type=["xlsx","xls"], label_visibility="collapsed", key="excel")

    df = None
    selected_row = None

    if excel_file:
        try:
            df = pd.read_excel(excel_file)
            fmt = detectar_formato(df)
            fmt_label = "🆕 Formato novo (Lista Semanal)" if fmt == "novo" else "📄 Formato antigo"
            st.success(f"✓ {len(df)} sinistro(s) carregado(s) · {fmt_label}")
        except Exception as e:
            st.error(f"Erro ao ler Excel: {e}")

    if df is not None:
        # ── Inicializar marcações na session_state ───────────────────────────
        if "marcados" not in st.session_state:
            st.session_state.marcados = set()
        if "excel_key" not in st.session_state:
            st.session_state.excel_key = ""

        excel_key = f"{len(df)}_{str(list(df.columns))}"
        if st.session_state.excel_key != excel_key:
            st.session_state.excel_key = excel_key
            st.session_state.marcados = set()

        # ── 2 · Todos os sinistros ───────────────────────────────────────────
        st.markdown('<p class="step-label" style="margin-top:20px">2 · Todos os sinistros</p>', unsafe_allow_html=True)

        search = st.text_input("🔍 Pesquisar", placeholder="nº sinistro, matrícula ou oficina…",
                               label_visibility="collapsed", key="search_all")

        mask = pd.Series([True] * len(df))
        if search.strip():
            q = search.strip().lower()
            mask = df.apply(
                lambda r: any(q in str(r.get(c,"")).lower()
                              for c in ["Nº sinistro","Matrícula","Nome da oficina","Nome prestador"]),
                axis=1
            )
        filtered_df = df[mask].reset_index(drop=False)

        if len(filtered_df) == 0:
            st.info("Nenhum sinistro encontrado.")
        else:
            for _, r in filtered_df.iterrows():
                orig_idx = int(r["index"])
                sin = str(r.get("Nº sinistro","")).strip()
                mat = str(r.get("Matrícula","")).strip()
                ofi = str(r.get("Nome da oficina","") or r.get("Nome prestador","")).strip()[:30]
                marcado = orig_idx in st.session_state.marcados

                checked = st.checkbox(
                    f"{sin}  ·  {mat}  ·  {ofi}",
                    value=marcado,
                    key=f"chk_{orig_idx}"
                )
                if checked and orig_idx not in st.session_state.marcados:
                    st.session_state.marcados.add(orig_idx)
                elif not checked and orig_idx in st.session_state.marcados:
                    st.session_state.marcados.discard(orig_idx)

        # ── 3 · Os meus sinistros ────────────────────────────────────────────
        n_marcados = len(st.session_state.marcados)
        st.markdown(f'<p class="step-label" style="margin-top:24px; color:#C8102E">3 · Os meus sinistros ({n_marcados} marcado(s))</p>', unsafe_allow_html=True)

        selected_row = None

        if n_marcados == 0:
            st.info("Assinale sinistros na lista acima para os ver aqui.")
        else:
            meus_rows = df[df.index.isin(st.session_state.marcados)].reset_index(drop=False)
            options_meus = []
            for _, r in meus_rows.iterrows():
                sin = str(r.get("Nº sinistro","")).strip()
                mat = str(r.get("Matrícula","")).strip()
                ofi = str(r.get("Nome da oficina","") or r.get("Nome prestador","")).strip()[:30]
                options_meus.append((f"🔴 {sin}  ·  {mat}  ·  {ofi}", int(r["index"])))

            labels_meus = [o[0] for o in options_meus]
            escolha = st.selectbox("Selecionar para gerar PDF", labels_meus,
                                   label_visibility="visible", key="sel_meus")
            orig_idx_meu = options_meus[labels_meus.index(escolha)][1]
            selected_row = df.iloc[orig_idx_meu]

with col_right:
    st.markdown('<p class="step-label">Dados do sinistro selecionado</p>', unsafe_allow_html=True)

    if selected_row is not None:
        preview_fields = get_preview_fields(df)
        rows_html = ""
        for label, col in preview_fields:
            val = selected_row.get(col, "")
            if pd.isna(val): val = "—"
            elif hasattr(val, "strftime"): val = val.strftime("%d/%m/%Y")
            else: val = str(val).strip() or "—"
            # Para Marca/Modelo juntar os dois campos
            if label == "Marca/Modelo":
                modelo = str(selected_row.get("Modelo", "")).strip()
                val = f"{val} {modelo}".strip() if val != "—" else "—"
            rows_html += f'<div class="info-row"><span class="info-key">{label}</span><span class="info-val">{val}</span></div>'
        st.markdown(f'<div class="info-card">{rows_html}</div>', unsafe_allow_html=True)
    else:
        st.markdown('<div class="info-card" style="color:#9CA3AF;font-size:0.9rem;text-align:center;padding:32px">Selecione um sinistro à esquerda</div>', unsafe_allow_html=True)

    st.markdown('<p class="step-label" style="margin-top:24px">3 · Suporte fotográfico (até 3 fotos)</p>', unsafe_allow_html=True)

    photo_cols = st.columns(3)
    photo_bytes_list = [None, None, None]

    for i, pcol in enumerate(photo_cols):
        with pcol:
            uploaded = st.file_uploader(f"Foto {i+1}", type=["jpg","jpeg","png","bmp","webp"],
                                        key=f"photo_{i}", label_visibility="visible")
            if uploaded:
                raw = uploaded.read()
                photo_bytes_list[i] = raw
                try:
                    st.image(Image.open(io.BytesIO(raw)), use_container_width=True)
                except:
                    pass

    st.markdown('<p class="step-label" style="margin-top:24px">4 · Textos do relatório</p>', unsafe_allow_html=True)

    # Inicializar session_state para os três campos
    for key, default in [("txt_obs",""), ("txt_perito",""), ("txt_oficina",""),
                         ("prev_sel_obs",""), ("prev_sel_perito",""), ("prev_sel_oficina","")]:
        if key not in st.session_state:
            st.session_state[key] = default

    def aplicar_frase(sel_key, txt_key, prev_key, frases):
        sel = st.selectbox(
            "frase", frases,
            key=sel_key, label_visibility="collapsed"
        )
        # Só atualiza o texto quando a seleção muda (e não é a opção vazia)
        if sel != st.session_state[prev_key]:
            st.session_state[prev_key] = sel
            st.session_state[txt_key] = "" if sel.startswith("—") else sel

    # Observações
    st.markdown("**Observações**")
    aplicar_frase("sel_obs", "txt_obs", "prev_sel_obs", FRASES_OBSERVACOES)
    texto_obs = st.text_area("obs", key="txt_obs", height=90,
                              label_visibility="collapsed",
                              placeholder="Selecione uma frase acima ou escreva aqui…")

    # Avalie o serviço do perito
    st.markdown("**Avalie o serviço do perito**")
    aplicar_frase("sel_perito", "txt_perito", "prev_sel_perito", FRASES_PERITO)
    texto_perito = st.text_area("perito", key="txt_perito", height=80,
                                 label_visibility="collapsed",
                                 placeholder="Selecione uma frase acima ou escreva aqui…")

    # Avalie o serviço da oficina
    st.markdown("**Avalie o serviço da oficina**")
    aplicar_frase("sel_oficina", "txt_oficina", "prev_sel_oficina", FRASES_OFICINA)
    texto_oficina = st.text_area("oficina", key="txt_oficina", height=80,
                                  label_visibility="collapsed",
                                  placeholder="Selecione uma frase acima ou escreva aqui…")

    st.markdown('<p class="step-label" style="margin-top:24px">5 · Gerar PDF</p>', unsafe_allow_html=True)

    can_generate = selected_row is not None

    if not can_generate:
        st.info("Carregue o Excel e selecione um sinistro para gerar o PDF.")

    if st.button("⬇ Gerar e Descarregar PDF", disabled=not can_generate):
        with st.spinner("A gerar PDF..."):
            try:
                pdf_bytes = fill_pdf_bytes(df, selected_row, photo_bytes_list,
                                           texto_obs, texto_perito, texto_oficina)
                sinistro = str(selected_row.get("Nº sinistro","sinistro")).strip()
                mat = str(selected_row.get("Matrícula","")).strip().replace("-","")
                filename = f"supervisao_{sinistro}_{mat}.pdf"
                st.download_button(
                    label="📥 Clique aqui para descarregar o PDF",
                    data=pdf_bytes,
                    file_name=filename,
                    mime="application/pdf",
                    use_container_width=True,
                )
                st.success(f"✓ PDF gerado com campos editáveis: {filename}")
            except Exception as e:
                st.error(f"Erro ao gerar PDF: {e}")
